contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logger, bool status, address keep) public payable {
        require(logger != address(0) && keep != address(0), "zero address not useful");
        // Ensure the test contract itself is not the owner and is not an approved logger initially.
        bool ownerIsSelf = (address(this) == msg.sender); // always true for calls from test? Actually msg.sender for c calls is this contract.
        // We will not try to be owner; we just test behavior for a non-approved caller.
        // First, read current approval state of our test contract as caller (this is the caller of c.logCreated).
        bool approvedBefore = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        // Call logCreated; it should return false because we are not approved.
        bool result = c.logCreated(keep); if (__ESBMC_reverted()) return;
        // After the call, our approval state must be unchanged (still false).
        bool approvedAfter = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        // The general rule: if the caller is not approved, logCreated returns false and does not grant approval.
        assert(!approvedBefore && !approvedAfter && !result);
    }

    receive() external payable {}
}

